'use strict';
(()=>{
 const entry=document.querySelector('[data-page="entry"]'),assets=document.querySelector('[data-page="assets"]');
 entry.setAttribute('aria-label','月度填报');assets.setAttribute('aria-label','账户与资产');
 const accountPanel=$('accountForm').closest('article');accountPanel.id='accountSetup';assets.prepend(accountPanel);accountPanel.querySelector('h2').textContent='第一步 · 建立资金账户';accountPanel.querySelector('.panel-head p').textContent='先添加银行卡、零钱或理财账户，并填纳入账本当天、流水发生前的余额。以后在这里新增或修改账户。';
 const welcome=document.createElement('article');welcome.className='panel onboarding';welcome.id='onboardingPanel';welcome.innerHTML='<h2>从这里开始，把家庭账本建起来</h2><ol class="workflow-steps"><li>建立资金账户，填写初始余额</li><li>每月录收入和转账，分别填成员支出月总额</li><li>核对月末各账户余额和持仓估值</li><li>检查齐全后关账，查看这个月的变化</li></ol><div class="actions"><a class="solid" href="#assets">建立 / 管理资金账户</a><a class="outline" href="#entry">开始月度填报</a></div><p id="onboardingStatus" class="muted"></p>';
 document.querySelector('[data-page="overview"]').prepend(welcome);
 const panel=document.createElement('article');panel.className='panel';panel.id='monthlyWorkflow';panel.innerHTML='<div class="panel-head"><div><h2>每月填报 · 一步步完成</h2><p>先录收入和转账，再填全家支出，最后核对月末余额。关账不自动进行，月初仍能补填上月。</p></div></div><div class="actions"><label class="field">填报月份<input id="workflowMonth" type="month"></label><button class="outline" id="previousMonth" type="button">填报上个月</button><button class="outline" id="refreshMonth" type="button">重新检查</button></div><ol class="workflow-steps"><li>录齐收入及内部转账</li><li>分别填写成员支出月总额</li><li>核对全部账户的月末余额 / 市值</li><li>确认并关账，查看月报</li></ol><p id="workflowStatus" role="status"></p><p id="workflowRequirements" class="muted"></p>';
 entry.prepend(panel);$('workflowMonth').value=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()).slice(0,7);$('workflowMonth').max=$('workflowMonth').value;
 const manual=$('manualForm').closest('article');manual.querySelector('h2').textContent='1 · 录收入和转账';manual.querySelector('.panel-head p').textContent='工资、奖金进入哪个账户就选哪个账户；内部转账另记，不算收入。生成草稿后在下方确认保存。';panel.after(manual);manual.after($('draftPanel'));$('draftPanel').after($('monthlyExpensePanel'));$('monthlyExpensePanel').querySelector('h2').textContent='2 · 填写全家本月支出';$('monthlyExpensePanel').querySelector('.status-tag').textContent='每人每月一个总额 · 家庭自动合计';
 const balances=document.createElement('article');balances.className='panel';balances.innerHTML='<h2>3 · 核对月末实际余额</h2><p>月中可保存截至当天的余额，月末再核对最终余额；未关账前可更正，空白项不覆盖。所有类型的账户都在这里填月末余额或总市值，也可在账户管理中用数量和单价更新。</p><form id="monthBalancesForm"><label class="field">余额截至日期<input id="monthBalanceDate" type="date" required></label><p class="muted" id="monthBalanceDateNote"></p><div id="monthBalanceFields" class="month-balance-grid"></div><button class="solid" id="saveMonthBalances" type="submit">保存本次填写的月末余额</button></form><div id="monthHoldingChecks"></div><a href="#assets">去统一账户管理 →</a><p id="monthBalanceResult" role="status"></p>';
 $('monthlyExpensePanel').after(balances);
 const closePanel=document.createElement('article');closePanel.className='panel';closePanel.innerHTML='<h2>4 · 检查并关账，看看本月发生了什么</h2><div id="monthSummary" class="expense-kpis"></div><p class="muted">资产变化减去已录收支后的差额，还可能包含汇率、投资估值和未录事项，不直接当作投资收益。缺少期初余额时不计算资产增量。</p><label><input id="monthIncomeConfirmed" type="checkbox"> 我确认本月收入和转账已录齐；没有收入也已核对</label><div class="actions"><button id="finishMonth" class="solid" type="button">确认关账</button><button id="reopenMonth" class="outline" type="button" hidden>重新打开本月（管理员）</button><button id="viewMonthReport" class="outline" type="button">查看本月图表</button></div><p id="finishMonthStatus" role="status"></p>';
 balances.after(closePanel);
 const more=document.createElement('details');more.className='panel';more.innerHTML='<summary>更多录入方式 · 粘贴助手整理结果、截图与示例</summary>';for(const child of [...entry.children])if(![panel,manual,$('draftPanel'),$('monthlyExpensePanel'),balances,closePanel].includes(child))more.append(child);entry.append(more);
 document.querySelector('[data-route="entry"] span').textContent='月度填报';pageInfo.entry=['月度填报','本月的账，一步步填清楚。','录收入 → 填支出 → 核余额 → 关账看变化'];pageInfo.assets=['账户与资产','先建账户，再确认钱在哪里。','资金账户、实际余额与股票持仓，统一在这里管理'];document.querySelector('[data-route="assets"] span').textContent='账户与资产';
 document.querySelector('#income h2').textContent='家庭成员的收入，一起看';
 const oldFamily=document.querySelector('#aiProvider').closest('.two-cols')?.querySelector('article');if(oldFamily&&!oldFamily.contains($('aiProvider')))oldFamily.remove();
 $('expenseMonth').parentElement.hidden=true;
 const extras=document.createElement('details');extras.className='full';extras.innerHTML='<summary>更多选项 · 发生时间和备注</summary>';$('manualForm').append(extras);extras.append($('recordTime').parentElement,$('recordMemo').parentElement);
 const balanceOption=[...$('recordKind').options].find(o=>o.value==='balance');balanceOption?.remove();
 const reportStatus=document.createElement('p');reportStatus.className='muted';$('reportControls').append(reportStatus);
 function renderReportStatus(r){const key=r.start.slice(0,7),closed=(D.periods||[]).find(p=>p.month===key);reportStatus.textContent=r.end.slice(0,7)===key?(closed?`${key} 已关账；月度总结已保存。`:`${key} 仍在填报中，金额可能继续变化。`):'此处按已保存数据实时汇总；月度填报页可查看每月是否已关账。';}
 globalThis.FamilyWorkflow={renderReportStatus};
 let review=null,sequence=0,first=true;
 function month(){return $('workflowMonth').value;}
 function selectMonth(){ $('expenseMonth').value=month();$('expenseMonth').dispatchEvent(new Event('change'));const end=new Date(Date.UTC(Number(month().slice(0,4)),Number(month().slice(5)),0)).toISOString().slice(0,10);$('recordDate').value=end<D.today?end:D.today;$('balanceDate').value=end<D.today?end:D.today;$('monthIncomeConfirmed').checked=false;loadReview();}
 function moneyField(id,label,cents){const a=document.createElement('article'),s=document.createElement('span'),v=document.createElement('strong');s.textContent=label;v.textContent=money(cents);a.append(s,v);$(id).append(a);}
 async function loadReview(){if(!D.live)return;const seq=++sequence;try{const r=await api('/api/periods/review?month='+encodeURIComponent(month()));if(seq!==sequence)return;review=r;
  $('workflowStatus').textContent=r.closed?`${r.month} 已关账 · ${new Date(r.closed.closedAt).toLocaleString('zh-CN')}`:`${r.month} 填报中 · 月末 ${r.end}`;
  const missing=r.checks.filter(c=>!c.done);$('workflowRequirements').textContent=`月末余额 / 估值：${r.checks.length-missing.length}/${r.checks.length} 已核对；月度支出：${r.expenseDone?'已填齐':'待填写整月总额'}。`+(r.end>=D.today?'本月尚未结束，可先保存截至当天的实际余额，月末再做最终核对。':'')+(!D.accounts.length?'请先到“账户与资产”建立资金账户。':'');
  const dateInput=$('monthBalanceDate'),maxDate=r.end<D.today?r.end:D.today,minDate=r.month+'-01';if(dateInput.value<minDate||dateInput.value>maxDate)dateInput.value=maxDate;dateInput.min=minDate;dateInput.max=maxDate;dateInput.disabled=!!r.closed;const asOf=dateInput.value;
  $('monthBalanceDateNote').textContent=asOf===r.end?'正在核对本月最后一天的实际余额。':'正在记录 '+asOf+' 的盘点余额，不会冒充尚未到来的月末余额；月末需再核对。';
  $('monthBalanceFields').replaceChildren();$('monthHoldingChecks').replaceChildren();
  for(const c of r.checks){if(c.kind==='持仓估值'){const p=document.createElement('p');p.textContent=`${c.done?'✓':'待核对'} · ${c.name} · ${r.end} 持仓估值`;$('monthHoldingChecks').append(p);continue;}const a=D.accounts.find(a=>a.id===c.id);if(a.startDate>asOf)continue;const wrap=document.createElement('div');wrap.className='monthly-account';const label=document.createElement('label');label.className='field';label.textContent=`${c.done?'✓ 已核对':'待核对'} · ${c.name}（${a.currency}）`;const input=document.createElement('input');input.type='number';input.min='0';input.step='0.01';input.dataset.account=c.id;input.placeholder='填写月末实际余额';input.disabled=!!r.closed;const saved=(D.records||[]).filter(x=>x.type==='balance'&&x.account===c.id&&x.date===asOf).at(-1);input.placeholder=saved?'已存 '+(saved.cents/100).toFixed(2)+'；填写可更正':'填写 '+asOf+' 实际余额';label.append(input);wrap.append(label);
   if(a.currency!=='CNY'){const fl=document.createElement('label');fl.className='field';fl.textContent=`手动确认 ${asOf} 汇率：1 ${a.currency} 折合人民币`;const fx=document.createElement('input');fx.type='number';fx.step='0.0000000001';fx.min='0.0000000001';fx.dataset.rateFor=c.id;fx.disabled=input.disabled;fx.placeholder='请填写该日参考汇率';fl.append(fx);wrap.append(fl);} $('monthBalanceFields').append(wrap);
  }
  $('finishMonth').disabled=!r.canClose||!!r.closed;document.getElementById('monthSummary').hidden=r.end>D.today;$('saveMonthBalances').disabled=!!r.closed||!r.checks.some(c=>c.kind==='余额'&&D.accounts.find(a=>a.id===c.id)?.startDate<=asOf);$('saveMonthBalances').textContent=asOf===r.end?'保存月末实际余额':'保存截至该日的实际余额';$('reopenMonth').hidden=!r.closed||window.currentFamilyUser?.role!=='admin';
  for(const form of [$('manualForm'),$('monthlyExpenseForm')])for(const el of form.querySelectorAll('input,select,button'))el.disabled=!!r.closed;
  $('monthSummary').replaceChildren();const s=r.closed?.summary||r.summary,confirmed=r.checks.length&&r.checks.every(c=>c.done);for(const [key,label]of [['incomeCents','本月收入'],['expenseCents','本月支出'],['netCents','收支结余'],['assetsCents',confirmed?'月末家庭资产':'资产参考值（待月底核对）'],['deltaCents',confirmed?'资产变化':'资产变化参考'],['unexplainedCents','扣除收支后的差额']])moneyField('monthSummary',label,s[key]);
 }catch(e){$('workflowStatus').textContent=e.message;}}
 $('monthBalanceDate').onchange=loadReview;$('workflowMonth').onchange=selectMonth;$('refreshMonth').onclick=loadReview;$('previousMonth').onclick=()=>{const d=new Date(D.today+'T00:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-1);$('workflowMonth').value=d.toISOString().slice(0,7);selectMonth();};
 $('monthBalancesForm').onsubmit=async e=>{e.preventDefault();if(!review)return;const records=[];for(const input of $('monthBalanceFields').querySelectorAll('[data-account]'))if(!input.disabled&&input.value!==''){const a=D.accounts.find(a=>a.id===input.dataset.account),r={type:'balance',date:$('monthBalanceDate').value,account:a.id,amount:input.value};if(a.currency!=='CNY'){const f=[...$('monthBalanceFields').querySelectorAll('[data-rate-for]')].find(x=>x.dataset.rateFor===a.id);if(!f.value){$('monthBalanceResult').textContent='外币余额请填写月末参考汇率。';return;}r.fx={rate:f.value,date:$('monthBalanceDate').value,source:'盘点手动确认汇率'};}records.push(r);}if(!records.length){$('monthBalanceResult').textContent='请先填写至少一个月末实际余额。';return;}
  $('saveMonthBalances').disabled=true;try{await api('/api/records/save',{data:{format:'family-assets-import',version:2,batchId:FamilyClient.newId(),records}});await refreshLedger();await loadReview();$('monthBalanceResult').textContent=$('monthBalanceDate').value===review.end?'月末余额已保存。':'截至 '+$('monthBalanceDate').value+' 的实际余额已保存；月末再做最终核对。';}catch(x){$('monthBalanceResult').textContent=x.message;}finally{loadReview();}
 };
 window.FamilyMonth={review:()=>review,reload:loadReview};
 $('finishMonth').onclick=async()=>{if(!review)return;$('finishMonth').disabled=true;try{await api('/api/periods/close',{month:month(),digest:review.digest,incomeConfirmed:$('monthIncomeConfirmed').checked});await refreshLedger();await loadReview();$('finishMonthStatus').textContent='本月已关账，总结已保存。可以查看本月图表。';}catch(e){$('finishMonthStatus').textContent=e.message;loadReview();}};
 $('reopenMonth').onclick=async()=>{try{await api('/api/periods/reopen',{month:month()});await refreshLedger();loadReview();$('finishMonthStatus').textContent='已重新打开。更正后请重新核对并关账。';}catch(e){$('finishMonthStatus').textContent=e.message;}};
 $('viewMonthReport').onclick=()=>{document.querySelector('[data-mode="month"]').click();$('period').value=month();preset();location.hash='#income';};
 function onData(){if(!D.live)return;$('onboardingStatus').textContent=D.registeredAccounts.length?`已建立 ${D.registeredAccounts.length} 个资金账户。接下来进入月度填报。`:'还没有资金账户。先点“建立 / 管理资金账户”，不要先填收入。';if(first){first=false;if(!D.registeredAccounts.length){location.hash='#assets';$('manageOwner').value=window.currentFamilyUser?.member||D.members[0]||'共同';}selectMonth();}else loadReview();}
 document.addEventListener('family-ledger-ready',onData);document.addEventListener('family-session-ready',()=>{if(review)$('reopenMonth').hidden=!review.closed||window.currentFamilyUser?.role!=='admin';});if(D.live)onData();route();
})();
